public struct MatchingPair: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let left: String
    public let right: String
}
public struct Question: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let prompt: String
    public let options: [Choice]
    public let answer: String
    public let explanation: String
    public let kind: String
    public let pairs: [MatchingPair]
    public let words: [Choice]
    public let answerWords: [String]
    enum CodingKeys: String, CodingKey { case id, prompt, options, answer, explanation, kind, pairs, words; case answerWords = "answer_words" }
    public init(id: String, prompt: String, options: [Choice], answer: String, explanation: String) {
        self.id = id; self.prompt = prompt; self.options = options; self.answer = answer; self.explanation = explanation
        kind = "choice"; pairs = []; words = []; answerWords = []
    }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id); prompt = try c.decode(String.self, forKey: .prompt)
        explanation = try c.decode(String.self, forKey: .explanation)
        kind = try c.decodeIfPresent(String.self, forKey: .kind) ?? "choice"
        options = try c.decodeIfPresent([Choice].self, forKey: .options) ?? []
        answer = try c.decodeIfPresent(String.self, forKey: .answer) ?? ""
        pairs = try c.decodeIfPresent([MatchingPair].self, forKey: .pairs) ?? []
        words = try c.decodeIfPresent([Choice].self, forKey: .words) ?? []
        answerWords = try c.decodeIfPresent([String].self, forKey: .answerWords) ?? []
    }
    public var correction: String {
        switch kind {
        case "matching": return pairs.map { "\($0.left) → \($0.right)" }.joined(separator: " · ")
        case "word_tiles": return answerWords.compactMap { id in words.first { $0.id == id }?.text }.joined(separator: " ")
        default: return options.first { $0.id == answer }?.text ?? answer
        }
    }
    var valid: Bool {
        func unique(_ ids: [String]) -> Bool { !ids.isEmpty && Set(ids).count == ids.count }
        switch kind {
        case "choice": return unique(options.map(\.id)) && options.contains { $0.id == answer }
        case "matching": return unique(pairs.map(\.id))
        case "word_tiles": return unique(words.map(\.id)) && unique(answerWords) && answerWords.allSatisfy { id in words.contains { $0.id == id } }
        default: return false
        }
    }
}
public struct CourseLesson: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let questions: [Question]
}
public struct Course: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let questions: [Question]
    public let lessons: [CourseLesson]
    enum CodingKeys: String, CodingKey { case id, title, questions, lessons }
    public init(id: String, title: String, questions: [Question]) {
        self.id = id; self.title = title; self.questions = questions; lessons = []
    }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id); title = try c.decode(String.self, forKey: .title)
        lessons = try c.decodeIfPresent([CourseLesson].self, forKey: .lessons) ?? []
        questions = try c.decodeIfPresent([Question].self, forKey: .questions) ?? lessons.flatMap(\.questions)
    }
    public var units: [CourseLesson] { lessons.isEmpty ? [CourseLesson(id: id, title: title, questions: questions)] : lessons }
    public func lessonCourse(_ index: Int) -> Course {
        let unit = units[index]
        return Course(id: unit.id, title: unit.title, questions: unit.questions)
    }
    public static func readFixture(_ url: URL) throws -> Course {
        struct DataSection: Decodable { let candidate_course: Course }
        struct Fixture: Decodable { let data: DataSection }
        let course = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url)).data.candidate_course
        guard !course.questions.isEmpty, Set(course.questions.map(\.id)).count == course.questions.count,
              Set(course.units.map(\.id)).count == course.units.count,
              course.units.allSatisfy({ !$0.questions.isEmpty }), course.questions.allSatisfy(\.valid) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return course
    }
}

public struct Lesson: Equatable, Sendable {
    public let course: Course
    public private(set) var position = 0
    public private(set) var selected: String?
    public private(set) var feedback: Bool?
    public private(set) var hearts = 5
    public private(set) var review = [Int]()
    public private(set) var reviewing = false
    public private(set) var complete = false
    public private(set) var selectedWords = [String]()
    public private(set) var matchedPairs = Set<String>()
    public private(set) var selectedLeft: String?
    public private(set) var selectedRight: String?
    public private(set) var matchingMistake = false
    public private(set) var pairNotice: String?
    public var question: Question { course.questions[position] }
    public var canSubmit: Bool {
        guard feedback == nil, !complete else { return false }
        switch question.kind {
        case "word_tiles": return !selectedWords.isEmpty
        case "matching": return matchedPairs.count == question.pairs.count
        default: return selected != nil
        }
    }
    public init(course: Course) { self.course = course }
    public mutating func choose(_ id: String) {
        guard feedback == nil, !complete, question.kind == "choice", question.options.contains(where: { $0.id == id }) else { return }
        selected = id
    }
    public mutating func addWord(_ id: String) {
        guard feedback == nil, !complete, question.kind == "word_tiles", !selectedWords.contains(id), question.words.contains(where: { $0.id == id }) else { return }
        selectedWords.append(id)
    }
    public mutating func removeWord(_ id: String) {
        guard feedback == nil, !complete else { return }
        selectedWords.removeAll { $0 == id }
    }
    public mutating func match(_ id: String, left: Bool) {
        guard feedback == nil, !complete, question.kind == "matching", !matchedPairs.contains(id), question.pairs.contains(where: { $0.id == id }) else { return }
        pairNotice = nil
        if left { selectedLeft = id } else { selectedRight = id }
        guard let a = selectedLeft, let b = selectedRight else { return }
        selectedLeft = nil; selectedRight = nil
        if a == b {
            matchedPairs.insert(a)
            pairNotice = "Pair matched"
            if matchedPairs.count == question.pairs.count { feedback = true }
        } else {
            matchingMistake = true
            recordMistake()
            pairNotice = "Try again. Those expressions have different meanings."
        }
    }
    private mutating func recordMistake() {
        hearts = max(0, hearts - 1)
        if !review.contains(position) { review.append(position) }
    }
    public mutating func submit() {
        guard canSubmit else { return }
        let correct: Bool
        switch question.kind {
        case "word_tiles": correct = selectedWords == question.answerWords
        case "matching": correct = true
        default: correct = selected == question.answer
        }
        feedback = correct
        if !correct { recordMistake() }
    }
    private mutating func clearAnswer() {
        selected = nil; feedback = nil; selectedWords = []; matchedPairs = []
        selectedLeft = nil; selectedRight = nil; matchingMistake = false; pairNotice = nil
    }
    public mutating func advance() {
        guard feedback != nil, !complete else { return }
        if reviewing {
            if feedback == true && !matchingMistake { review.removeAll { $0 == position } }
        } else if position + 1 < course.questions.count {
            position += 1; clearAnswer(); return
        } else { reviewing = true }
        if let next = review.first { position = next }
        else { complete = true }
        clearAnswer()
    }
}

public struct LearningProgress: Codable, Equatable, Sendable {
    public var completedCourses: Set<String> = []
    public init() {}
    public func isComplete(_ course: Course, index: Int) -> Bool { completedCourses.contains(course.units[index].id) || completedCourses.contains(course.id) }
    public func isUnlocked(_ course: Course, index: Int) -> Bool { index == 0 || isComplete(course, index: index - 1) }
    public func completedCount(_ course: Course) -> Int { course.units.indices.filter { isComplete(course, index: $0) }.count }
}
public struct ProgressStore: Sendable {
    public let url: URL
