@MainActor @Observable final class LearningModel {
    let course: Course
    let store: ProgressStore
    var progress: LearningProgress
    var lesson: Lesson?
    var currentLesson = 0
    var confirmingExit = false
    var error: String?
    init(course: Course, store: ProgressStore) throws {
        self.course = course
        self.store = store
        progress = try store.load()
    }
    func start(_ index: Int) {
        guard progress.isUnlocked(course, index: index) else { return }
        currentLesson = index
        lesson = Lesson(course: course.lessonCourse(index))
        confirmingExit = false
    }
    func saveCompletion() {
        var updated = progress
        updated.completedCourses.insert(course.units[currentLesson].id)
        if updated.completedCount(course) == course.units.count { updated.completedCourses.insert(course.id) }
        do { try store.save(updated); progress = updated; error = nil }
        catch { self.error = "Progress could not be saved. Please try again." }
    }
    func advance() {
        lesson?.advance()
        if lesson?.complete == true {
            saveCompletion()
        }
    }
}

